import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.BoXUJ6sC.js";const m=JSON.parse('{"title":"팀 규칙 (필수)","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/team-rules.md","filePath":"kafka/team-rules.md"}'),c={name:"kafka/team-rules.md"};function a(n,t,s,l,i,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="팀-규칙-필수" tabindex="-1">팀 규칙 (필수) <a class="header-anchor" href="#팀-규칙-필수" aria-label="Permalink to &quot;팀 규칙 (필수)&quot;">​</a></h1><table tabindex="0"><thead><tr><th>항목</th><th>규칙</th></tr></thead><tbody><tr><td>토픽</td><td><code>kidly.{보내는도메인}.events</code>. 보내는 도메인마다 하나이며, 그 도메인이 보내는 이벤트는 종류와 관계없이 모두 이 토픽에 넣습니다</td></tr><tr><td>표기</td><td>소문자만 씁니다. 단계는 <code>.</code>, 단어는 <code>-</code>로 구분합니다. <code>_</code>, 대문자, 환경 이름, 버전은 넣지 않습니다</td></tr><tr><td>파티션 · 복제</td><td>3 · 1. 만든 뒤에는 파티션 수를 바꾸지 않습니다. 늘리면 키가 들어가는 파티션이 바뀌어 순서가 깨집니다</td></tr><tr><td>토픽 생성</td><td>보내는 도메인이 <code>NewTopic</code> 빈으로 만듭니다. 받는 도메인은 자기 DLT만 만듭니다. 브로커의 토픽 자동 생성은 꺼져 있습니다</td></tr><tr><td>키</td><td><code>event.correlationId()</code></td></tr><tr><td>본문</td><td>JSON 문자열. 공통 칸 7개(<code>eventId</code>, <code>eventType</code>, <code>schemaVersion</code>, <code>occurredAt</code>, <code>producer</code>, <code>aggregateId</code>, <code>correlationId</code>) + <code>data</code>. 이벤트 record를 그대로 JSON으로 바꾸면 5칸이 빠지므로(5칸은 필드가 아니라 <code>DomainEvent</code>의 기본 메서드) 보내는 쪽이 직접 채웁니다</td></tr><tr><td>헤더</td><td><code>eventType</code>, <code>eventId</code>(본문과 같은 값). Java 타입 헤더 <code>__TypeId__</code>는 쓰지 않습니다</td></tr><tr><td>값</td><td>ID는 <code>Long</code>(JSON 숫자). 시각은 <code>LocalDateTime</code> ISO 문자열이며 한국 시간이고 시간대 표시를 붙이지 않습니다. <code>data</code>가 없는 메시지는 보내지 않습니다</td></tr><tr><td>이벤트 변경</td><td>필드는 <strong>추가만</strong> 합니다(삭제, 이름 변경, 타입 변경 금지). 개인정보 필드를 더 넣지 않습니다</td></tr><tr><td>모르는 필드</td><td>받는 쪽은 <strong>모르는 필드를 무시합니다</strong>(Jackson 3, spring-kafka 기본값이며 이 설정을 바꾸지 않습니다)</td></tr><tr><td>새 enum 값</td><td><strong>받는 쪽을 먼저 배포</strong>한 뒤 보냅니다</td></tr><tr><td>읽기 실패</td><td>모르는 enum 값처럼 메시지를 읽지 못하면 null로 읽거나 건너뛰지 않습니다. <strong>재시도 없이 DLT로 보내고 Slack으로 알립니다</strong>(<code>READ_UNKNOWN_ENUM_VALUES_AS_NULL</code>을 켜지 않습니다)</td></tr><tr><td>보내는 시점</td><td><strong>DB 커밋이 확정된 뒤에만</strong> 보냅니다. 방법은 도메인 자율입니다(4절)</td></tr><tr><td>구독 그룹</td><td><code>kidly.{받는도메인}</code></td></tr><tr><td>DLT</td><td><code>{토픽}.{받는도메인}.dlt</code>, 파티션 1. 받는 도메인이 만듭니다. 처리는 사람이 확인한 뒤 그 받는 도메인이 DLT를 읽는 별도 consumer로 다시 합니다. <strong>원래 토픽에 다시 넣지 않습니다.</strong> &quot;나중에 다시 하기&quot;용 retry 토픽은 쓰지 않습니다. DLT 전송기(<code>DeadLetterPublishingRecoverer</code>)의 기본 목적지(<code>{토픽}-dlt</code>, 원래 파티션 번호)는 쓰지 않고, 목적지를 이 이름과 파티션 <code>-1</code>(Kafka가 고름)로 지정합니다(3절 리스너 설정 예시)</td></tr><tr><td>자기 이벤트</td><td>자기 도메인 이벤트는 Kafka로 받지 않고 Spring 이벤트로 받습니다(member의 <code>member.withdrawn</code>, product의 <code>product.changed</code>)</td></tr><tr><td>로그</td><td>메시지 본문을 로그와 예외 메시지에 넣지 않습니다. 남기는 것은 <code>eventType</code>, <code>eventId</code>, 키뿐입니다(본문의 개인정보가 Kafka와 DLT에 7일 남습니다)</td></tr></tbody></table><h2 id="한-앱-kidly-app-인-동안의-공용-규칙" tabindex="-1">한 앱(<code>kidly-app</code>)인 동안의 공용 규칙 <a class="header-anchor" href="#한-앱-kidly-app-인-동안의-공용-규칙" aria-label="Permalink to &quot;한 앱(`kidly-app`)인 동안의 공용 규칙&quot;">​</a></h2><p>여러 도메인이 한 앱에 있어서, 아래를 어기면 다른 도메인이 깨집니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>규칙</th></tr></thead><tbody><tr><td>앱 설정</td><td>Kafka 설정은 앱 <code>application.yml</code> 한 곳에만 있습니다. String 직렬화, <code>acks=all</code>, <code>enable.idempotence=true</code>, <code>auto-offset-reset: latest</code>가 들어 있고 <code>max.block.ms</code>와 브로커 <code>offsets.retention.minutes</code>는 기본값입니다</td></tr><tr><td>도메인 yml</td><td><code>spring.kafka.*</code>를 넣지 않습니다. 나중에 불러온 도메인 yml이 앞의 값을 조용히 덮어씁니다. 도메인 값은 자기 리스너 설정 코드에 둡니다</td></tr><tr><td>빈</td><td><code>KafkaTemplate</code>, <code>ProducerFactory</code>, <code>ConsumerFactory</code>를 도메인에서 빈으로 새로 만들지 않습니다(Boot 기본 빈이 사라집니다)</td></tr><tr><td>빈 이름</td><td>도메인이 만드는 컨테이너 팩토리와 에러 처리기 빈은 도메인 이름을 앞에 붙입니다(<code>{도메인}KafkaListenerContainerFactory</code>). 이름이 겹치면 앱이 뜨지 않습니다</td></tr><tr><td>에러 처리기</td><td>자기 컨테이너 팩토리에 직접 붙입니다. 에러 처리기 빈이 앱에 둘 이상이면 Boot가 기본 팩토리에 아무것도 붙이지 않습니다</td></tr><tr><td>의존성</td><td><code>spring-boot-starter-kafka</code>를 <code>kidly.domain</code> 빌드 플러그인으로 모든 도메인이 받습니다. 도메인 빌드 파일에 따로 넣지 않습니다</td></tr><tr><td>보내기 스위치</td><td>커밋 뒤 Kafka로 보내는 빈(아웃박스를 쓰면 릴레이 스케줄러)에는 <code>@ConditionalOnProperty(name = &quot;kidly.kafka.producer.enabled&quot;, havingValue = &quot;true&quot;, matchIfMissing = true)</code>를 붙입니다. Kafka 컨테이너가 없는 테스트는 이 값을 꺼서 보내지 않습니다</td></tr><tr><td>전송 실패 로그</td><td>앱은 Boot 기본 <code>KafkaTemplate</code>의 전송 실패를 토픽 · 키 · <code>eventType</code> · <code>eventId</code>와 예외로 남기고 본문은 남기지 않습니다(앱 설정). 받는 쪽 DLT 전송기처럼 Boot 기본 템플릿을 쓰는 곳은 따로 할 일이 없습니다</td></tr><tr><td>직접 만든 템플릿</td><td><code>new KafkaTemplate&lt;&gt;(...)</code>으로 만든 템플릿에는 앱 설정이 붙지 않고, 기본 실패 로그가 키와 본문을 그대로 남깁니다. 만들 때 <code>setProducerListener(new ProducerListener&lt;&gt;() {})</code>로 기본 실패 로그를 끄고, 실패는 자기 코드에서 <code>eventType</code> · <code>eventId</code> · 키로 남깁니다</td></tr></tbody></table>',5)])])}const u=d(c,[["render",a]]);export{m as __pageData,u as default};
